{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_includes_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_uses_last_input_record_then_sorts():
    events = parse_session_log(["a,5,1", "z,2,1", "a,2,0", "c,1,1"])
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]


def test_parse_session_log_fields_and_skipped_lines():
    assert parse_session_log(["", " \t", "  # comment", " a , 2 , 0 ", " b , 3 , "]) == [
        {"id": "a", "day": 2, "converted": False},
        {"id": "b", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("line", ["a,1", "a,2,1,extra", "a,no,0"])
def test_parse_errors_include_physical_line_number(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", "a,1,1", " # ignore", line])


def test_daily_counts_fill_range_and_ignore_outside_events():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,4,1"])
    assert daily_conversion_counts(events, 1, 3) == [0, 2, 0]
    assert daily_conversion_counts(events, 4, 3) == []


def test_trailing_window_boundaries():
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 4) == 6


def test_pooled_summary_weights_sessions_and_uses_calendar_days():
    groups = {"a": parse_session_log(["a,1,1", "b,1,0"]), "b": parse_session_log(["c,5,0"]), "c": []}
    assert pooled_conversion_rate(groups) == 1 / 3
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rates_and_ranking_order():
    groups = {"z": [{"converted": True}], "b": [{"converted": False}], "empty": [], "a": [{"converted": False}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", 0.0), ("b", 0.0), ("empty", None), ("z", 1.0)]
    assert top_converting_groups(groups, 2) == ["z", "a"]
    assert top_converting_groups(groups, 10) == ["z", "a", "b"]


def test_streak_counts_only_consecutive_positive_entries():
    assert longest_conversion_streak([1, 2, -1, 3, 0, 4]) == 2
    assert longest_conversion_streak([]) == 0
    assert longest_conversion_streak([-1, 0]) == 0
